import sys

class Node:
    __slots__ = ('key', 'left', 'right', 'height')
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1

def height(node):
    return 0 if node is None else node.height

def update_height(node):
    if node is not None:
        node.height = 1 + max(height(node.left), height(node.right))

def balance_factor(node):
    return 0 if node is None else height(node.left) - height(node.right)

def right_rotate(y):
    x = y.left
    T2 = x.right
    x.right = y
    y.left = T2
    update_height(y)
    update_height(x)
    return x

def left_rotate(x):
    y = x.right
    T2 = y.left
    y.left = x
    x.right = T2
    update_height(x)
    update_height(y)
    return y

def rebalance(node):
    if node is None:
        return None
    update_height(node)
    bal = balance_factor(node)

    # Left Heavy
    if bal > 1:
        if balance_factor(node.left) < 0:
            node.left = left_rotate(node.left)
        return right_rotate(node)

    # Right Heavy
    if bal < -1:
        if balance_factor(node.right) > 0:
            node.right = right_rotate(node.right)
        return left_rotate(node)

    return node

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
    elif key > root.key:
        root.right = insert(root.right, key)
    else:
        # Duplicate keys are ignored
        return root
    return rebalance(root)

def min_value_node(node):
    cur = node
    while cur is not None and cur.left is not None:
        cur = cur.left
    return cur

def delete(root, key):
    if root is None:
        return None
    if key < root.key:
        root.left = delete(root.left, key)
    elif key > root.key:
        root.right = delete(root.right, key)
    else:
        if root.left is None:
            return root.right
        if root.right is None:
            return root.left
        # Two children: get inorder successor
        succ = min_value_node(root.right)
        root.key = succ.key
        root.right = delete(root.right, succ.key)
    return rebalance(root)

def inorder(root, out):
    if root is not None:
        inorder(root.left, out)
        out.append(str(root.key))
        inorder(root.right, out)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    values = list(map(int, data[1:1+N]))
    K = int(data[1+N]) if len(data) > 1+N else 0

    root = None
    for v in values:
        root = insert(root, v)

    root = delete(root, K)

    out = []
    inorder(root, out)
    sys.stdout.write(" ".join(out) + "\n")

if __name__ == "__main__":
    solve()
